"""Generate on-device assets for the ESP32 sketch (Chinese / UTF-8 version).

Fixes the ASCII-only assumption in gen_assets.py:
  - Uses the ByteLevel alphabet to extract raw bytes per token directly,
    without going through a Python string decode that would fail on byte
    fragments (partial UTF-8 sequences that exist in any ByteLevel BPE vocab).

Outputs:
  firmware/esp32_llm/vocab.h  -- token id -> raw UTF-8 bytes (VOCAB_BLOB / VOCAB_OFF)
"""

import os

from tokenizers import Tokenizer

HERE   = os.path.dirname(os.path.abspath(__file__))
TOK    = os.path.join(HERE, "..", "data", "bpe8192_zh.json")
OUT    = os.path.join(HERE, "..", "firmware", "esp32_llm", "vocab.h")
PROMPT = "从前，有一只小兔子"


def _build_byte_decoder() -> dict:
    """Invert the GPT-2 byte→unicode map used by the ByteLevel pre-tokeniser.

    ByteLevel.alphabet() returns chars sorted by Unicode code-point, NOT by
    byte value, so enumerate(alphabet()) would assign wrong byte values.
    We re-derive the mapping from the original GPT-2 recipe instead.
    """
    bs = (
        list(range(ord("!"), ord("~") + 1))    # 33-126  printable ASCII
        + list(range(ord("¡"), ord("¬") + 1))  # 161-172
        + list(range(ord("®"), ord("ÿ") + 1))  # 174-255
    )
    cs = list(bs)
    n = 0
    for b in range(256):
        if b not in bs:
            bs.append(b)
            cs.append(256 + n)
            n += 1
    return {chr(c): b for b, c in zip(bs, cs)}  # unicode_char -> byte_value


_BYTE_DEC = _build_byte_decoder()


def token_to_raw_bytes(tok: Tokenizer, token_id: int) -> bytes:
    """Return the raw bytes that this token represents.

    For complete-character tokens (e.g. '小') this gives b'\\xe5\\xb0\\x8f'.
    For byte-fragment tokens it gives the partial byte sequence.
    For special tokens like <|endoftext|> it returns b'' (nothing to write).
    Concatenating the raw bytes of all tokens in a sequence reconstructs the
    original UTF-8 text exactly.
    """
    s = tok.id_to_token(token_id)
    if s is None:
        return b""
    return bytes(_BYTE_DEC[c] for c in s if c in _BYTE_DEC)


def main():
    tok = Tokenizer.from_file(TOK)
    V = tok.get_vocab_size()

    # Verify roundtrip on the demo prompt before writing anything
    ids = tok.encode(PROMPT).ids
    raw = b"".join(token_to_raw_bytes(tok, i) for i in ids)
    recovered = raw.decode("utf-8")
    assert recovered == PROMPT, f"roundtrip mismatch: {recovered!r} != {PROMPT!r}"
    print(f"roundtrip OK: {PROMPT!r}")

    # Build blob: raw bytes per token, offsets mark boundaries
    blob = bytearray()
    offs = [0]
    for i in range(V):
        blob.extend(token_to_raw_bytes(tok, i))
        offs.append(len(blob))

    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    with open(OUT, "w", encoding="utf-8") as f:
        f.write("// Generated by src/gen_assets_zh.py -- token id -> raw UTF-8 bytes.\n")
        f.write("#ifndef VOCAB_H\n#define VOCAB_H\n")
        f.write(f"#define VOCAB_N {V}\n")
        f.write(f"static const unsigned char VOCAB_BLOB[{len(blob)}] = {{\n")
        for i in range(0, len(blob), 20):
            f.write("  " + ",".join(str(b) for b in blob[i:i+20]) + ",\n")
        f.write("};\n")
        f.write(f"static const int VOCAB_OFF[{len(offs)}] = {{\n")
        for i in range(0, len(offs), 20):
            f.write("  " + ",".join(str(o) for o in offs[i:i+20]) + ",\n")
        f.write("};\n#endif\n")

    print(f"wrote {OUT}: {V} tokens, blob {len(blob)/1024:.0f} KB")

    print(f'\nprompt "{PROMPT}" -> {len(ids)} ids: {ids}')
    print("\nPaste into the sketch:")
    print(f"static const int PROMPT_IDS[] = {{{', '.join(map(str, ids))}}};")


if __name__ == "__main__":
    main()
